import{_ as e,o as a,c as t,a4 as r}from"./chunks/framework.hWlsC8BY.js";const d=JSON.parse('{"title":"AI种稻 永丰村300亩稻田“算”出丰收","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"AI种稻 永丰村300亩稻田“算”出丰收","date":"2026-09-17T00:00:00.000Z","source":"中国农业信息网","category":"news","link":"https://www.agri.cn/xxh/zhny/202609/t20260917_8871881.htm","summary":"●永丰村 300 亩试点田首次应用水稻专属AI大模型管理，从“凭经验看田”转向靠数据辅助决策\\n●AI测算分析出9月15日为最佳开镰日期，预计亩产量为880—895公斤\\n●崇州、新都等地同步探索，“算力守田”在“天府粮仓”多点开花\\n9月7日，眉山市东坡区太和镇永丰村里，连片稻田翻着金浪。种粮大户邵国东站在田埂上，望着即将开镰的300亩稻田，满脸笑意。...\\n","contentHash":"3dddc4cb73c3a5dcdd711be0b083de3e","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-09-17-AI种稻-永丰村300亩稻田-算-出丰收.md","filePath":"news/2026-09-17-AI种稻-永丰村300亩稻田-算-出丰收.md"}'),n={name:"news/2026-09-17-AI种稻-永丰村300亩稻田-算-出丰收.md"};function _(s,p,A,I,o,l){return a(),t("div",null,[...p[0]||(p[0]=[r('<h1 id="ai种稻-永丰村300亩稻田-算-出丰收" tabindex="-1">AI种稻 永丰村300亩稻田“算”出丰收 <a class="header-anchor" href="#ai种稻-永丰村300亩稻田-算-出丰收" aria-label="Permalink to &quot;AI种稻 永丰村300亩稻田“算”出丰收&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.agri.cn/xxh/zhny/202609/t20260917_8871881.htm" target="_blank" rel="noreferrer">中国农业信息网</a><br> 日期: 2026-09-17 摘要: ●永丰村 300 亩试点田首次应用水稻专属AI大模型管理，从“凭经验看田”转向靠数据辅助决策 ●AI测算分析出9月15日为最佳开镰日期，预计亩产量为880—895公斤 ●崇州、新都等地同步探索，“算力守田”在“天府粮仓”多点开花 9月7日，眉山市东坡区太和镇永丰村里，连片稻田翻着金浪。种粮大户邵国东站在田埂上，望着即将开镰的300亩稻田，满脸笑意。...</p></blockquote><p>●永丰村 300 亩试点田首次应用水稻专属AI大模型管理，从“凭经验看田”转向靠数据辅助决策</p><p>●AI测算分析出9月15日为最佳开镰日期，预计亩产量为880—895公斤</p><p>●崇州、新都等地同步探索，“算力守田”在“天府粮仓”多点开花</p><p>9月7日，眉山市东坡区太和镇永丰村里，连片稻田翻着金浪。种粮大户邵国东站在田埂上，望着即将开镰的300亩稻田，满脸笑意。不少游客、研学团队正在田边“打卡”拍照，在他们眼中，这片稻田和别处的高产稻田没有区别。</p><p>没有遍地显眼的机器人，也没有密密麻麻的新设备，很少有人知道，这片看似普通的稻田，是村里首批应用水稻专属AI大模型管理的试点田。</p><p>看不见的北斗卫星在天上定位，传感器埋在田间，AI藏在小程序后台，从插秧、水肥调控到病虫害预警，这一季水稻的田间管理，从“凭经验看田”，转向了靠数据、靠算法辅助决策。丰收在望的稻浪底下，一场“算力守田”的种粮试验，在永丰村落地。</p><p>把栽培知识装进AI大模型</p><p>“我以为AI种稻时，田里会摆满新奇设备，到了地头才发现完全不是这么回事。”记者抛出疑问。</p><p>四川农业大学水稻栽培专家马均解释，这恰恰是这套技术的特别之处：北斗在天上、无人机按需出动、AI大模型在云端，肉眼看不见，但农户打开“东坡巡田”小程序就能连上整套系统。</p><p>这片 300 亩试点田，是四川省水稻新品种新技术中试研发平台今年的核心成果展示田，由马均团队主导搭建了水稻专属AI大模型。团队做的第一件事，是把几十年积累的水稻栽培专业知识、永丰村多年的大田生产数据，包括生育期规律、土壤基线、气象历史、水肥方案、农机作业记录、历年产量品质等，一一入库“喂养”模型。</p><p>土壤墒情传感器、水位监测、虫情诱捕设备，加上卫星遥感、无人机巡田、人工下地复核，多渠道持续回传苗情、水情、灾情数据。AI根据实时数据自动判读生育阶段和长势，匹配地块属性、品种特性、天气预报，输出分田块、分时段的补水、追肥、防控农事建议。</p><p>“不是替代农民全自动种稻，更像24小时在岗的专业参谋。”邵国东直呼，这一季种得省心。</p><p>不少种业从业者也盯上了这片试点田。浙江勿忘农种业股份有限公司的张乐乐专程来到田间，300亩试点田里种了好几个他们选育的新品种。“很多好品种潜力强，但配套栽培技术跟不上，优势就发挥不出来，这次相当于给新品种配上了专属的精准栽培体系，是非常难得的试错场景。”张乐乐说。</p><p>值得一提的是，这 300亩试点田的收割最佳时间和预估产量，也是 AI 算出来的。“我们将无人机‘扫田’的数据输入后，AI分析出9月15日是最佳开镰日期，预计亩产量为880—895公斤。”四川农业大学副教授、四川东坡永丰水稻科技小院院长杨志远告诉记者。</p><p>永丰村凭什么先“跑”起来</p><p>为什么 AI 种稻首片试点田落在永丰村？答案不仅仅在于算法，更在于这片田多年攒下的“硬底子”。</p><p>作为全省水稻新品种新技术中试研发平台的核心基地、“天府粮仓”建设标杆村，永丰村不是从零起步做AI，前期已经完成了高标准农田建设、全程机械化操作、数字化监测等铺垫工作。</p><p>在永丰村，连片规整的高标准农田宜机化全覆盖，耕种收全流程机械化早已跑通，当地水稻平均亩产稳定在780公斤；田间物联网监测点位数字化覆盖率达到92%，水质、水深、墒情、虫情、气象数据常年积累，再叠加马均团队20多年600多个品种、数十项栽培技术的中试台账，这些凑齐了训练农业AI 最稀缺、最宝贵的高质量田间数据集。</p><p>换言之，永丰村人早就入局了智慧农业：先修良田、配农机、铺好感知网络、跑通数字化台账，再往上叠加AI决策层。村干部、种植户、农技员早就习惯用手机看田块数据、远程调度，“东坡巡田”小程序有现成的用户基础，农户接受门槛低，天然适合做AI种稻试点。</p><p>也正因此，马均团队选择先控制成本、小范围验证，目前仅完成300亩试点。杨志远透露，专用AI模型“高质量数据‘喂’得越多，模型迭代进化越快，用户用起来越精准”。</p><p>“我们的模型现阶段仍处于学习迭代期，难免会给出不合理建议。”杨志远坦言，现阶段模型输出的农事方案必须经过农技人员人工把关校验，“但随着模型的快速迭代，失误率会急速降低，离媲美农艺专家的目标并不遥远。”</p><p>迭代训练AI种稻将多点开花</p><p>为了融合作物栽培机理和算法能力，目前四川农业大学团队正联合电子科技大学专家开展跨学科协作，共同训练、打磨这款水稻垂直领域AI大模型：农学团队负责把关农业逻辑、田间试验设计、标签数据质量，电子科大团队负责算法架构、多源数据融合、模型轻量化、成本优化。</p><p>“持续‘投喂’数据，模型就最懂这片稻田；以后导入川南、川东、川北等不同稻区的本地化数据，就能适配不同生态区的种稻场景。”杨志远介绍，当前核心目标是优先打磨模型可靠性、降低部署成本，再逐步扩大示范面积。</p><p>放眼全川，永丰村不是四川唯一探索点位，“算力守田”正在“天府粮仓”多点开花。</p><p>成都崇州市已连续举办两届“天府粮仓”人工智能水稻种植挑战赛，AI决策团队和资深种粮“老把式”同田竞技。去年5月，由中国农业科学院都市农业研究所研发的“人工智能水稻种植决策智能体”为4名农户提供AI辅助种植指导，与6名传统种植农户展开了对比试验。</p><p>成都市新都区军屯省级智慧无人示范农场600亩核心区，由省农科院朱从桦团队打造，围绕稻麦轮作、AI作物模型+精准灌溉、无人巡田、高温稳产管控方向建设，走出了一条智慧生产路径。</p><p>今年四川省委一号文件提出，顺应当前新一轮科技革命与产业变革加速发展态势，发展智慧农业，支持有条件的地方建设智慧农业引领区。从永丰村的300亩水稻试点，到崇州的人工智能水稻种植挑战赛，再到新都的无人农场——算力，正成为“天府粮仓”的“新农具”。（四川农村日报全媒体记者 袁宇君）</p><p><a href="https://www.agri.cn/xxh/zhny/202609/t20260917_8871881.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',31)])])}const i=e(n,[["render",_]]);export{d as __pageData,i as default};
